#include <vector>
#include <numeric>

class Solution {
public:
    int compareSumsOfBitonicParts(std::vector<int>& nums) {
        int n = nums.size();
        int peak = 0;
        while (peak + 1 < n && nums[peak] < nums[peak + 1]) {
            peak++;
        }
        long long leftSum = 0, rightSum = 0;
        for (int i = 0; i <= peak; ++i) leftSum += nums[i];
        for (int i = peak; i < n; ++i) rightSum += nums[i];
        if (leftSum > rightSum) return 0;
        if (rightSum > leftSum) return 1;
        return -1;
    }
};

